import{_ as o,l,o as a,c as i,v as t,p as s,x as n,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"线段相交 Bentley–Ottmann","description":"","frontmatter":{"title":"线段相交 Bentley–Ottmann","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/segment-intersection.md","filePath":"cs/segment-intersection.md","lastUpdated":1789023840000}'),h={name:"cs/segment-intersection.md"};function m(B,e,_,u,E,A){const r=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="线段相交-bentley–ottmann" tabindex="-1">线段相交 Bentley–Ottmann <a class="header-anchor" href="#线段相交-bentley–ottmann" aria-label="Permalink to &quot;线段相交 Bentley–Ottmann&quot;">​</a></h1><div class="epigraph"><p>扫描线维护与竖线相交的线段 $y$ 序；只有相邻才可能先交，交点入事件队列，$O((n+I)\\log n)$ 报出 $I$ 个交点。</p><footer>—— 据 Bentley and Ottmann, Algorithms for Reporting and Counting Geometric Intersections, 1979；CLRS 第 33.2 节整理</footer></div><p>上一课<a href="/cs/closest-pair">最近点对</a>是点。线段两两交朴素 \\(O(n^2)\\)。缺口是 Bentley–Ottmann：端点与交点当事件，平衡树邻接。不重写矩形扫描。后课半平面交。精度问题收到鲁棒性课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一般位置：无三线共点、无竖线（旋转或特殊处理）。事件：左端插入、右端删除、交点交换相邻。只有树中相邻线段检测交。输出所有交或是否存在。</p><p>缺口是邻接不变式，不是暴力。</p><h3 id="交点必须当事件" tabindex="-1">交点必须当事件 <a class="header-anchor" href="#交点必须当事件" aria-label="Permalink to &quot;交点必须当事件&quot;">​</a></h3><p>只扫端点会漏「后来才相邻」的交。BO 把交点插入队列。优先队列键为 \\(x\\)。</p><p><span class="marginnote">Bentley–Ottmann 1979。Chazelle 有更细理论。后课半平面交用对偶或双端队列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件堆。扫描状态平衡树（按当前 \\(x\\) 的 \\(y\\)）。插入/删/交换后检查新邻对。退化情况单独分支。</p>',11)),(a(),s(p,null,{default:n(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E7%AB%AF%E7%82%B9%E4%B8%8E%E4%BA%A4%E7%82%B9%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20YORD%5B%22%E6%89%AB%E6%8F%8F%20y%20%E5%BA%8F%22%5D%0A%20%20YORD%20--%3E%20NBR%5B%22%E5%8F%AA%E6%B5%8B%E7%9B%B8%E9%82%BB%22%5D%0A%20%20NBR%20--%3E%20I%5B%22I%20%E4%B8%AA%E4%BA%A4%E7%82%B9%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>计数 \\(I\\) 可达 \\(\\Theta(n^2)\\)，算法输出敏感。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最先发生的交必来自当时相邻对。交换后新相邻再测。与扫描线面积：结构都是线上序，事件种类多了交点。与平面图叠加同一家族。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理全部退化的工业实现。曲线弧不写。后课默认：线段交输出敏感扫描。下一课半平面交。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>相邻线段才可能下一个交。</li><li>\\(O((n+I)\\log n)\\)。</li><li>交点入队列；注意退化。</li><li>出处：Bentley and Ottmann, 1979；CLRS 第 33.2 节。</li></ul>',7))])}const T=o(h,[["render",m]]);export{b as __pageData,T as default};
